/**
 * Learning Hub layout ΓÇö the nested four-section navigator inside the
 * candidate tree.
 *
 * `/learn` used to be a single screen (the catalogue). It is now a nested
 * `Tabs` layout: the parent candidate navigator sees exactly one route
 * (`learn`) and never the hub's children, and this navigator owns its own
 * bottom bar ({@link LearningHubTabBar}) ΓÇö which is why the main candidate bar
 * renders nothing while the hub is open (`CandidateTabBar`), so two bars can
 * never be stacked on screen.
 *
 * Transitions: sections cross-fade over 220 ms (`motion` band, 180ΓÇô280 ms) and
 * collapse to an instant switch when the system asks for reduced motion. Tabs
 * stay lazy-mounted and retained, so a section keeps its scroll position and
 * state across switches, and `backBehavior="history"` makes Android Back walk
 * the sections the user actually visited before leaving the hub for the
 * candidate tab it was opened from.
 */

import { Tabs } from 'expo-router';
import { Easing } from 'react-native';

import { LearningHubTabBar } from '@/features/navigation/LearningHubTabBar';
import { LEARNING_HUB_TABS, learningHubScreenNameForPath } from '@/config/navConfig';
import { useReducedMotion } from '@/lib/useReducedMotion';
import { colors, motion } from '@/theme/tokens';

/** The section cross-fade, inside the required 180ΓÇô280 ms band. */
export const HUB_SECTION_TRANSITION = {
  animation: 'timing' as const,
  config: { duration: 220, easing: Easing.out(Easing.cubic) },
};

export default function LearningHubLayout() {
  const reducedMotion = useReducedMotion();

  return (
    <Tabs
      backBehavior="history"
      tabBar={(props) => <LearningHubTabBar {...props} />}
      screenOptions={{
        headerShown: false,
        tabBarHideOnKeyboard: true,
        // The scene is pre-painted in the page colour, so switching sections
        // never flashes white or black while the destination mounts.
        sceneStyle: { backgroundColor: colors.colorBgPage },
        animation: reducedMotion ? 'none' : 'fade',
        transitionSpec: reducedMotion ? undefined : HUB_SECTION_TRANSITION,
      }}>
      {LEARNING_HUB_TABS.map((tab) => (
        <Tabs.Screen
          key={tab.name}
          name={learningHubScreenNameForPath(tab.path)}
          options={{
            title: tab.label,
            tabBarAccessibilityLabel: tab.label,
          }}
        />
      ))}
    </Tabs>
  );
}

/**
 * Learning Hub ΓÇö Home: the video-first learning feed.
 *
 * Data spine, all real server rows:
 *  - `GET /courses` ΓÇö the catalogue page, on the same cache key the Courses
 *    section uses, so the two screens share one request;
 *  - `GET /courses/{id}` for a bounded slice of it ΓÇö the only way the server
 *    exposes lectures at all (there is no lecture-feed endpoint), and the same
 *    key the course-detail screen uses, so opening a course reuses the cache;
 *  - `GET /courses/enrollments/mine` ΓÇö the genuine Continue Learning rows.
 *
 * Loading, error, empty and refresh states are decided in the pure
 * `hubFeedView` model: a failure is a persistent banner with retry, never an
 * empty feed, and a `null` duration renders no duration at all.
 */

import { useCallback, useMemo, useState } from 'react';
import { FlatList, RefreshControl, StyleSheet, View } from 'react-native';
import { useQueries, useQuery } from '@tanstack/react-query';
import { useRouter } from 'expo-router';

import { fetchCourse, fetchCourses, fetchMyEnrollments } from '@/api/courses';
import { queryKeys } from '@/api/queryKeys';
import { AppText } from '@/components/ui/AppText';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { CourseCard } from '@/components/ui/CourseCard';
import { SkeletonCard } from '@/components/ui/Skeleton';
import { StatusBanner } from '@/components/ui/StatusBanner';
import { enrolledCountLabel, myLearningView } from '@/features/learn/myLearningModel';
import { FeaturedLectureCard } from '@/features/learningHub/FeaturedLectureCard';
import { HubHeader } from '@/features/learningHub/HubHeader';
import { LectureCard } from '@/features/learningHub/LectureCard';
import {
  FEED_COURSE_LIMIT,
  buildLectureFeed,
  categoriesFromCourses,
  hubFeedView,
} from '@/features/learningHub/learningHubModel';
import { colors, radius, spacing } from '@/theme/tokens';

const CATALOGUE_PAGE_SIZE = 20;

export default function LearningHubHomeScreen() {
  const router = useRouter();

  const coursesQuery = useQuery({
    queryKey: queryKeys.courses(),
    queryFn: () => fetchCourses({ page_size: CATALOGUE_PAGE_SIZE }),
    staleTime: 30_000,
  });
  const courses = useMemo(() => coursesQuery.data?.items ?? [], [coursesQuery.data]);
  const feedCourses = useMemo(() => courses.slice(0, FEED_COURSE_LIMIT), [courses]);

  // One small detail request per catalogue course, in catalogue order ΓÇö the
  // model pairs `details[i]` with `courses[i]`.
  const detailQueries = useQueries({
    queries: feedCourses.map((course) => ({
      queryKey: queryKeys.course(course.id),
      queryFn: () => fetchCourse(course.id),
      staleTime: 60_000,
    })),
  });

  const enrollmentsQuery = useQuery({
    queryKey: queryKeys.myEnrollments,
    queryFn: () => fetchMyEnrollments({ page_size: 10 }),
    staleTime: 30_000,
  });

  const items = buildLectureFeed(
    feedCourses,
    detailQueries.map((query) => query.data ?? null),
  );
  const feedView = hubFeedView({
    coursesHasData: coursesQuery.data !== undefined,
    coursesLoading: coursesQuery.isPending,
    coursesError: coursesQuery.error,
    detailsPending: detailQueries.filter((query) => query.isPending).length,
    detailsFailed: detailQueries.filter((query) => query.isError).length,
    detailError: detailQueries.find((query) => query.error)?.error ?? null,
    items,
  });
  const learningView = myLearningView(enrollmentsQuery);
  const categories = useMemo(() => categoriesFromCourses(courses), [courses]);

  const featured = feedView.kind === 'ready' ? feedView.featured : null;
  const feedItems =
    feedView.kind === 'ready'
      ? feedView.items.filter((item) => item.lectureId !== featured?.lectureId)
      : [];

  const refetchEverything = useCallback(() => {
    void Promise.all([
      coursesQuery.refetch(),
      enrollmentsQuery.refetch(),
      ...detailQueries.map((query) => query.refetch()),
    ]);
  }, [coursesQuery, enrollmentsQuery, detailQueries]);

  const openCourse = (courseId: string) => router.push(`/course/${courseId}` as never);
  const openLecture = (lectureId: string, courseId: string) => router.push(`/lecture/${lectureId}?courseId=${courseId}` as never);
  const openCoursesSection = () => router.push('/learn/courses' as never);
  const openUploadSection = () => router.push('/learn/upload' as never);
  const openSearch = () =>
    router.push({
      pathname: '/learn/courses',
      // A fresh stamp each time, so re-tapping search re-focuses the field
      // even when the Courses screen is already mounted.
      params: { focusSearch: String(Date.now()) },
    } as never);

  const continueSection = () => {
    if (learningView.kind === 'loading') {
      return <SkeletonCard lines={3} />;
    }
    if (learningView.kind === 'error') {
      return (
        <StatusBanner
          title="Couldn't load your enrolled courses"
          description={learningView.message}
          onRetry={() => void enrollmentsQuery.refetch()}
        />
      );
    }
    if (learningView.kind === 'empty') {
      return (
        <Card>
          <View style={styles.emptyState}>
            <AppText variant="body" weight="semibold">
              {"You haven't enrolled in any courses yet."}
            </AppText>
            <AppText variant="small" tone="secondary">
              Enrol from the catalogue and a course shows up here so you can pick it up any time.
            </AppText>
            <Button
              label="Browse courses"
              variant="secondary"
              fullWidth
              onPress={openCoursesSection}
            />
          </View>
        </Card>
      );
    }
    return (
      <View>
        {learningView.refreshError ? (
          <View style={styles.banner}>
            <StatusBanner
              title="Couldn't refresh your enrolled courses"
              description={learningView.refreshError}
              onRetry={() => void enrollmentsQuery.refetch()}
            />
          </View>
        ) : null}
        <AppText variant="caption" tone="tertiary" style={styles.continueCount}>
          {enrolledCountLabel(learningView.total)}
        </AppText>
        <FlatList
          horizontal
          showsHorizontalScrollIndicator={false}
          data={learningView.items}
          keyExtractor={(item) => item.enrollment.id}
          contentContainerStyle={styles.continueList}
          renderItem={({ item }) => (
            <View style={styles.continueCard}>
              <CourseCard
                course={item.course}
                enrolledAt={item.enrollment.created_at}
                onPress={(course) => openCourse(course.id)}
              />
            </View>
          )}
        />
      </View>
    );
  };


  /** The "All" chip plus the derived categories; counts come from the loaded page. */
  const chips: { id: string; name: string; course_count: number }[] = [
    { id: '', name: 'All', course_count: -1 },
    ...categories,
  ];

  const feedEmptyState = () => {
    if (feedView.kind === 'loading') {
      return (
        <View style={styles.states} testID="hub-feed-loading">
          <SkeletonCard />
          <SkeletonCard />
          <SkeletonCard />
        </View>
      );
    }
    if (feedView.kind === 'error') {
      return (
        <View style={styles.states} testID="hub-feed-error">
          <StatusBanner
            title="Couldn't load lectures"
            description={
              feedView.message ?? 'The learning catalogue could not be reached just now.'
            }
            onRetry={refetchEverything}
          />
        </View>
      );
    }
    return (
      <View style={styles.states} testID="hub-feed-empty">
        <Card>
          <View style={styles.emptyState}>
            <AppText variant="h3" weight="semibold">
              No lectures published yet
            </AppText>
            <AppText variant="small" tone="secondary">
              Video lectures appear here as creators publish courses with a curriculum. Nothing is
              shown until the server has real lecture records.
            </AppText>
            <View style={styles.emptyActions}>
              <Button label="Browse courses" variant="secondary" fullWidth onPress={openCoursesSection} />
              <Button label="Upload a lecture" variant="ghost" fullWidth onPress={openUploadSection} />
            </View>
          </View>
        </Card>
      </View>
    );
  };

  const listHeader = (
    <View>
      <HubHeader
        title="MahaJob Learning"
        subtitle="Learn skills. Build your future."
        onSearch={openSearch}
        testID="learning-hub-header"
      />

      <View style={styles.section}>
        <AppText variant="label" tone="secondary" uppercase style={styles.sectionTitle}>
          Continue learning
        </AppText>
        {continueSection()}
      </View>

      {feedView.kind === 'ready' && featured ? (
        <View style={styles.section}>
          <AppText variant="label" tone="secondary" uppercase style={styles.sectionTitle}>
            Featured lecture
          </AppText>
          <FeaturedLectureCard item={featured} onPress={(item) => openLecture(item.lectureId, item.courseId)} />
        </View>
      ) : null}

      {chips.length > 1 ? (
        <View style={styles.section}>
          <AppText variant="label" tone="secondary" uppercase style={styles.sectionTitle}>
            Categories
          </AppText>
          <FlatList
            horizontal
            showsHorizontalScrollIndicator={false}
            data={chips}
            keyExtractor={(item) => item.id || 'all'}
            contentContainerStyle={styles.chipList}
            renderItem={({ item }) => (
              <View style={styles.chip}>
                <AppText variant="small" weight="semibold" numberOfLines={1}>
                  {item.name}
                </AppText>
                {item.course_count >= 0 ? (
                  <AppText variant="caption" tone="tertiary" uppercase>
                    {item.course_count} course{item.course_count === 1 ? '' : 's'}
                  </AppText>
                ) : null}
              </View>
            )}
          />
        </View>
      ) : null}

      {feedView.kind === 'ready' && feedView.items.length > 0 ? (
        <AppText
          variant="label"
          tone="secondary"
          uppercase
          style={[styles.sectionTitle, styles.discoverTitle]}>
          Discover lectures
        </AppText>
      ) : null}
    </View>
  );


  return (
    <View style={styles.root} testID="learning-hub-home">
      <FlatList
        testID="hub-feed-list"
        data={feedItems}
        keyExtractor={(item) => item.lectureId}
        ListHeaderComponent={listHeader}
        ListEmptyComponent={feedEmptyState()}
        contentContainerStyle={styles.listContent}
        renderItem={({ item }) => (
          <View style={styles.feedRow}>
            <LectureCard item={item} onPress={(lecture) => openLecture(lecture.lectureId, lecture.courseId)} />
          </View>
        )}
        refreshControl={
          <RefreshControl
            refreshing={coursesQuery.isRefetching}
            onRefresh={refetchEverything}
            tintColor={colors.colorPrimary}
            colors={[colors.colorPrimary]}
          />
        }
      />
    </View>
  );
}

const styles = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: colors.colorBgPage,
  },
  listContent: {
    paddingBottom: spacing.xl,
  },
  section: {
    paddingHorizontal: spacing.pagePadding,
    marginBottom: spacing.lg,
  },
  sectionTitle: {
    marginBottom: spacing.sm,
  },
  discoverTitle: {
    paddingHorizontal: spacing.pagePadding,
    marginBottom: spacing.sm,
  },
  banner: {
    marginBottom: spacing.sm,
  },
  continueCount: {
    marginBottom: spacing.xs,
  },
  continueList: {
    gap: spacing.sm,
    paddingRight: spacing.pagePadding,
  },
  continueCard: {
    width: 264,
  },
  chipList: {
    gap: spacing.sm,
    paddingRight: spacing.pagePadding,
  },
  chip: {
    backgroundColor: colors.colorBgSurface,
    borderColor: colors.colorBorder,
    borderRadius: radius.full,
    borderWidth: 1,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.sm,
    minWidth: 96,
    alignItems: 'center',
  },
  chipPressed: {
    opacity: 0.6,
  },
  chipSelected: {
    backgroundColor: colors.colorPrimarySubtle,
    borderColor: colors.colorPrimary,
  },
  states: {
    paddingHorizontal: spacing.pagePadding,
    gap: spacing.sm,
    paddingBottom: spacing.lg,
  },
  emptyState: {
    gap: spacing.sm,
    alignItems: 'flex-start',
  },
  emptyActions: {
    alignSelf: 'stretch',
    gap: spacing.sm,
    marginTop: spacing.xs,
  },
  feedRow: {
    paddingHorizontal: spacing.pagePadding,
    marginBottom: spacing.sm,
  },
});

∩╗┐/**
 * Candidate Messages ├óΓé¼ΓÇ¥ the Message section.
 *
 * Three internal tabs live *inside* this screen (All / Unread / Requests) below
 * the search field; the global bottom navigation is untouched. The screen is
 * about **conversations**: the All pane reads the real conversation list from
 * the main backend's `/conversations` router, Unread narrows the same list to
 * threads with a server-reported `unread_count`, and Requests lists the
 * pending **message requests** from the independent message service.
 *
 * **No connection-request surface lives here.** Incoming connection requests are
 * handled through Home ├óΓÇáΓÇÖ the notification bell ├óΓÇáΓÇÖ `/notifications`, and the full
 * request surface (including a link into the person's profile) stays in
 * `/connections`. A message request is permission to message ├óΓé¼ΓÇ¥ a different
 * table, a different service, a different resolution ├óΓé¼ΓÇ¥ and accepting one here
 * never touches a connection, and vice versa.
 */

import { useMemo, useState } from 'react';
import { useRouter } from 'expo-router';
import { Pressable, StyleSheet, View } from 'react-native';
import { useQuery } from '@tanstack/react-query';

import { ApiError } from '@/api/errors';
import { listConversations, type Conversation } from '@/api/messages';
import { useAuth } from '@/auth/AuthContext';
import { AppText } from '@/components/ui/AppText';
import { AppIcon } from '@/components/ui/AppIcon';
import { Avatar } from '@/components/ui/Avatar';
import { Card } from '@/components/ui/Card';
import { Screen } from '@/components/ui/Screen';
import { SkeletonCard } from '@/components/ui/Skeleton';
import { StatusBanner } from '@/components/ui/StatusBanner';
import { otherParticipant } from '@/features/conversation/conversationModel';
import { RequestCard } from '@/features/messages/RequestCard';
import { MessageSearchField } from '@/features/messages/MessageSearchField';
import { MessageSectionTabs } from '@/features/messages/MessageSectionTabs';
import {
  conversationPreview,
  filterConversations,
  filterRequests,
  formatRequestTime,
  isConversationUnread,
  type MessageSectionId,
} from '@/features/messages/messageSections';
import { useMessageRequests } from '@/features/messages/useMessageRequests';
import { messagingQueryKeys } from '@/realtime/queryBridge';
import { colors, radius, spacing } from '@/theme/tokens';

export default function CandidateMessagesScreen() {
  const router = useRouter();
  const [active, setActive] = useState<MessageSectionId>('all');
  const [search, setSearch] = useState('');

  const requests = useMessageRequests();

  /*
   * The thread list itself: one `GET /conversations` page, shared by the All
   * and Unread panes and by the tab bar's unread dot. It lives at the screen
   * level rather than inside a pane so switching tabs never refetches and two
   * panes can never disagree about what "unread" means ├óΓé¼ΓÇ¥ both read the same
   * server `unread_count`.
   */
  const conversations = useQuery({
    queryKey: messagingQueryKeys.conversations,
    queryFn: () => listConversations(),
    // The realtime bridge invalidates this key on a socket event, and the
    // focus refetch corrects it when the reader returns to the Messages tab.
    refetchOnWindowFocus: true,
  });

  const loaded = useMemo(() => conversations.data?.items ?? [], [conversations.data]);
  const unreadThreadCount = useMemo(
    () => loaded.filter((row) => isConversationUnread(row)).length,
    [loaded],
  );

  // Local filters over the rows the user already holds ├óΓé¼ΓÇ¥ never a claim to
  // search every server-side conversation.
  const visibleConversations = useMemo(
    () => filterConversations(loaded, search),
    [loaded, search],
  );
  const visibleUnread = useMemo(
    () => visibleConversations.filter((row) => isConversationUnread(row)),
    [visibleConversations],
  );

  const visibleRequests = useMemo(
    () => filterRequests(requests.requests, search),
    [requests.requests, search],
  );

  // Every press is a pane switch now: the Connections/Companies destinations
  // left this screen with the connection-request surface, and there is nothing
  // to navigate to from the tab bar itself.
  const handleSelect = (id: MessageSectionId) => setActive(id);

  return (
    <Screen testID="messages-screen">
      <View style={styles.stack}>
        <View style={styles.header}>
          <AppText variant="h1" accessibilityRole="header">
            Messages
          </AppText>
          <View style={styles.headerActions}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="New message"
              accessibilityHint="Opens your connections to start a conversation"
              hitSlop={8}
              onPress={() => router.push('/connections' as never)}
              style={styles.iconButton}>
              <AppIcon name={{ ios: 'square.and.pencil', android: 'edit' }} size={22} />
            </Pressable>
          </View>
        </View>

        <MessageSearchField value={search} onChangeText={setSearch} />

        <MessageSectionTabs
          active={active}
          pendingCount={requests.pendingCount}
          unreadThreadCount={unreadThreadCount}
          onSelect={handleSelect}
        />

        <View style={styles.body}>
          {active === 'all' ? (
            <ConversationsPane
              conversations={visibleConversations}
              search={search}
              isLoading={conversations.isPending}
              errorMessage={conversations.isError ? conversationErrorMessage(conversations.error) : null}
              onRetry={() => void conversations.refetch()}
              emptyTitle="No conversations yet"
              emptyDescription="Connect with somebody and start a conversation ├óΓé¼ΓÇ¥ it will appear here."
            />
          ) : null}
          {active === 'unread' ? (
            <ConversationsPane
              conversations={visibleUnread}
              search={search}
              isLoading={conversations.isPending}
              errorMessage={conversations.isError ? conversationErrorMessage(conversations.error) : null}
              onRetry={() => void conversations.refetch()}
              emptyTitle="No unread messages"
              emptyDescription="You're all caught up. New messages will show up here."
            />
          ) : null}
          {active === 'requests' ? (
            <RequestsTab view={requests} visible={visibleRequests} />
          ) : null}
        </View>
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({
  stack: {
    gap: spacing.lg,
  },
  header: {
    alignItems: 'center',
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  headerActions: {
    flexDirection: 'row',
    gap: spacing.sm,
  },
  iconButton: {
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: 48,
    minWidth: 48,
  },
  body: {
    gap: spacing.md,
  },
  list: {
    gap: spacing.md,
  },
  rowHeader: {
    alignItems: 'center',
    flexDirection: 'row',
    gap: spacing.md,
  },
  rowIdentity: {
    flex: 1,
    gap: 2,
  },
  rowMeta: {
    alignItems: 'flex-end',
    gap: spacing.xs,
  },
  rowPressed: {
    opacity: 0.85,
  },
  unreadBadge: {
    alignItems: 'center',
    backgroundColor: colors.colorPrimary,
    borderRadius: radius.full,
    minWidth: 20,
    paddingHorizontal: 6,
    paddingVertical: 1,
  },
});

/** The server's own message when the inbox failed, else a generic transport line. */
function conversationErrorMessage(error: unknown): string {
  return error instanceof ApiError
    ? error.message
    : 'The API did not answer. Check your connection and try again.';
}

/**
 * The thread list, shared by the All and Unread panes.
 *
 * Loading, error and empty are all honest: the skeletons are real latency, the
 * error names the server's message with a retry, and each empty state says which
 * pane you are in rather than pretending the account has no threads at all. No
 * fabricated threads, no client-computed unread counts ├óΓé¼ΓÇ¥ members, previews and
 * `unread_count` come straight from the server.
 */
function ConversationsPane({
  conversations: visible,
  search,
  isLoading,
  errorMessage,
  onRetry,
  emptyTitle,
  emptyDescription,
}: {
  conversations: Conversation[];
  search: string;
  isLoading: boolean;
  errorMessage: string | null;
  onRetry: () => void;
  emptyTitle: string;
  emptyDescription: string;
}) {
  if (isLoading) {
    return (
      <View style={styles.list}>
        <SkeletonCard lines={2} />
        <SkeletonCard lines={2} />
      </View>
    );
  }

  if (errorMessage) {
    return <StatusBanner title="Could not load your conversations" description={errorMessage} onRetry={onRetry} />;
  }

  if (visible.length === 0) {
    return (
      <StatusBanner
        tone="info"
        title={search.trim().length > 0 ? 'No conversations match your search' : emptyTitle}
        description={
          search.trim().length > 0 ? 'Try a different name or word.' : emptyDescription
        }
      />
    );
  }

  return (
    <View style={styles.list} testID="conversations-list">
      {visible.map((conversation) => (
        <ConversationRow key={conversation.id} conversation={conversation} />
      ))}
    </View>
  );
}

/**
 * One thread in the list ├óΓé¼ΓÇ¥ tapping it opens the one-to-one conversation screen
 * for that conversation id. The name/avatar are the *other* member: the caller
 * is in `members` too, and "you" beside every preview would be noise.
 *
 * Unread is the server's count, shown as a count badge (not just bold text), and
 * the row states it in its accessibility label so a screen reader reads the same
 * fact the badge shows.
 */
function ConversationRow({ conversation }: { conversation: Conversation }) {
  const router = useRouter();
  const { principal } = useAuth();
  // The avatar/name are the *other* member: the caller is in members too,
  // resolved by internal user id so the caller's own photo is never shown.
  const selfUserId = principal?.id ?? null;
  const primary = otherParticipant(conversation.members, selfUserId);
  const preview = conversationPreview(conversation);
  const time = conversation.last_message_at ? formatRequestTime(conversation.last_message_at) : '';
  const unread = conversation.unread_count;

  const open = () => router.push(`/conversation/${conversation.id}` as never);

  return (
    <Pressable
      onPress={open}
      accessibilityRole="button"
      accessibilityLabel={`Conversation with ${primary?.name ?? 'a connection'}${
        unread > 0 ? `, ${unread} unread` : ''
      }`}
      accessibilityHint="Opens the conversation"
      testID={`conversation-${conversation.id}`}
      style={({ pressed }) => [pressed ? styles.rowPressed : null]}>
      <Card>
        <View style={styles.rowHeader}>
          <Avatar
            name={primary?.name ?? 'Conversation'}
            src={primary?.avatar_url ?? null}
            size={40}
          />
          <View style={styles.rowIdentity}>
            <AppText variant="body" weight={unread > 0 ? 'bold' : 'semibold'} numberOfLines={1}>
              {primary?.name ?? 'Conversation'}
            </AppText>
            {preview ? (
              <AppText variant="small" tone="secondary" numberOfLines={1}>
                {preview}
              </AppText>
            ) : null}
          </View>
          <View style={styles.rowMeta}>
            {time ? (
              <AppText variant="caption" tone="tertiary">
                {time}
              </AppText>
            ) : null}
            {unread > 0 ? (
              <View style={styles.unreadBadge}>
                <AppText variant="caption" weight="bold" tone="onPrimary">
                  {unread > 99 ? '99+' : unread}
                </AppText>
              </View>
            ) : null}
          </View>
        </View>
      </Card>
    </Pressable>
  );
}

function RequestsTab({
  view,
  visible,
}: {
  view: ReturnType<typeof useMessageRequests>;
  visible: ReturnType<typeof filterRequests>;
}) {
  if (view.isLoading) {
    return (
      <View style={styles.list}>
        <SkeletonCard lines={3} />
        <SkeletonCard lines={3} />
      </View>
    );
  }

  if (view.loadError) {
    return (
      <StatusBanner
        title="Could not load your requests"
        description={view.loadError}
        onRetry={view.retryLoad}
      />
    );
  }

  if (view.requests.length === 0) {
    return (
      <StatusBanner
        tone="info"
        title="No message requests"
        description="When someone asks to message you, their request will appear here for you to accept or reject."
      />
    );
  }

  if (visible.length === 0) {
    return (
      <StatusBanner
        tone="info"
        title="No requests match your search"
        description="Try a different name or detail."
      />
    );
  }

  return (
    <View style={styles.list} testID="requests-list">
      {visible.map((request) => {
        const busy = view.busyId === request.id;
        const cardError = view.actionErrorId === request.id ? view.actionError : null;
        return (
          <RequestCard
            key={request.id}
            request={request}
            busy={busy}
            error={cardError}
            onAccept={() => view.accept(request.id)}
            onReject={() => view.reject(request.id)}
          />
        );
      })}
    </View>
  );
}

/**
 * Notifications ΓÇö the candidate's inbox for connection requests and events.
 *
 * Read from the main backend's `/notifications` router (see
 * `src/api/notifications.ts`): the caller's own rows, newest first, with the
 * server-rendered `title` and optional `body` as their text. Only a
 * `connection_request` addressed to the caller carries Accept / Reject, because
 * that is the one event whose resolution routes exist and whose direction the
 * server enforces ΓÇö every other type is informational.
 *
 * **Incoming requests live here, not in the Message section.** `GET
 * /connections` is the same data filtered another way, so this screen is one
 * read of the server's own event log rather than a second source of truth for
 * request state. Accepting sends `POST /connections/{id}/accept` and rejecting
 * sends `ΓÇª/decline`; both wait for the server's answer and then invalidate the
 * inbox, the badge count and the connections list together, which is why the
 * bell, this screen and the Connections screen agree after every taper:
 * they all re-read.
 */
import { Pressable, StyleSheet, View } from 'react-native';
import { useMemo, useState } from 'react';

import { AppText } from '@/components/ui/AppText';
import { Avatar } from '@/components/ui/Avatar';
import { BackButton } from '@/components/ui/BackButton';
import { Button } from '@/components/ui/Button';
import { Screen } from '@/components/ui/Screen';
import { SkeletonCard } from '@/components/ui/Skeleton';
import { StatusBanner } from '@/components/ui/StatusBanner';
import { colors, layout, spacing } from '@/theme/tokens';
import { connectionIdFromNotification, type Notification } from '@/api/notifications';
import {
  actorName,
  filterNotificationsByCategory,
  formatNotificationTime,
  isUnread,
  notificationAction,
  notificationSubtitle,
} from '@/features/notifications/notificationModel';
import { useRouter } from 'expo-router';
import type { NotificationCategory } from '@/features/notifications/notificationModel';
import { useUnreadNotificationCount } from '@/features/notifications/useNotifications';
import { useNotifications, type NotificationsView } from '@/features/notifications/useNotifications';

const CATEGORIES: ReadonlyArray<{
  id: NotificationCategory | 'all';
  label: string;
}> = [
  { id: 'all', label: 'All' },
  { id: 'requests', label: 'Requests' },
  { id: 'activity', label: 'Activity' },
];

export default function CandidateNotificationsScreen() {
  const view = useNotifications();
  const router = useRouter();
  const unreadCount = useUnreadNotificationCount();
  const [activeCategory, setActiveCategory] = useState<NotificationCategory | 'all'>('all');
  const [unreadOnly, setUnreadOnly] = useState(false);
  const filteredNotifications = useMemo(() => {
    // 'all' shows the whole inbox; every other tab is one category bucket.
    if (activeCategory === 'all') return view.notifications;
    const all = filterNotificationsByCategory(view.notifications, activeCategory);
    if (!unreadOnly) return all;
    return all.filter((notification) => isUnread(notification));
  }, [view.notifications, activeCategory, unreadOnly]);

  // Requests carries the server's pending count. Every other bucket is purely
  // informational and must never print a number the client cannot have.
  const requestLabel = view.pendingCount > 0 ? `Requests (${view.pendingCount})` : 'Requests';

  return (
    <Screen testID="notifications-screen">
      <BackButton />

      <AppText variant="h1" accessibilityRole="header" style={styles.title}>
        Notifications
      </AppText>

      {view.isLoading ? (
        <View style={styles.stack}>
          <SkeletonCard lines={2} />
          <SkeletonCard lines={2} />
        </View>
      ) : null}

      {!view.isLoading && view.loadError ? (
        <StatusBanner
          title="Couldn't load your notifications"
          description={view.loadError}
          onRetry={view.retryLoad}
        />
      ) : null}

      {!view.isLoading && !view.loadError && view.notifications.length === 0 ? (
        <StatusBanner
          tone="info"
          title="You're all caught up"
          description="Connection requests and updates will appear here."
        />
      ) : null}

      {!view.isLoading && !view.loadError && view.notifications.length > 0 ? (
        <>
          {/* Category tabs. Only the Requests tab prints the server's pending
           * count; every other bucket is informational and prints nothing. */}
          <View style={styles.tabBar} accessibilityRole="tablist">
            {CATEGORIES.map((category) => {
              const isActive = category.id === activeCategory;
              const label = category.id === 'requests'
                ? requestLabel
                : category.label;
              return (
                <Pressable
                  key={category.id}
                  accessibilityRole="tab"
                  accessibilityState={{ selected: isActive }}
                  onPress={() => setActiveCategory(category.id)}
                  style={({ pressed }) => [
                    styles.tab,
                    isActive ? styles.tabActive : null,
                    pressed && styles.tabPressed,
                  ]}>
                  <AppText
                    variant="small"
                    weight={isActive ? 'semibold' : 'regular'}
                    tone={isActive ? 'onPrimary' : 'secondary'}>
                    {label}
                  </AppText>
                </Pressable>
              );
            })}
          </View>

          {/* Filters and actions ΓÇö unread-only display and a single-pass clear.
           * Both are server-truth driven and never optimistically changed. */}
          <View style={styles.toolbar}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={
                unreadOnly
                  ? 'Show all notifications'
                  : 'Show only unread notifications'
              }
              onPress={() => setUnreadOnly((current) => !current)}
              style={styles.toolbarButton}>
              <AppText variant="caption" weight="semibold">
                {unreadOnly ? 'Unread' : 'All'}
              </AppText>
            </Pressable>

            {view.notifications.length > 0 && unreadCount.count > 0 ? (
              <Button
                label="Mark all read"
                variant="ghost"
                onPress={view.markAll}
                style={styles.toolbarButton}
              />
            ) : null}
          </View>

          <View style={styles.list} testID="notifications-list">
            {filteredNotifications.map((notification) => (
              <NotificationRow key={notification.id} notification={notification} view={view} />
            ))}
          </View>
        </>
      ) : null}
    </Screen>
  );
}

/**
 * One event, and its resolution when the server says one exists.
 *
 * The name and avatar come from the notification's own `actor` ΓÇö three fields
 * the server attached, so this row never needs a second request to say who
 * knocked. Tapping anywhere but the action buttons marks the row read; the row
 * body itself navigates nowhere, because a notification is an event log, not a
 * profile link. The full request surface (including a link into the person's
 * profile) stays in `/connections`.
 */
function NotificationRow({
  notification,
  view,
}: {
  notification: Notification;
  view: NotificationsView;
}) {
  const router = useRouter();
  const action = notificationAction(notification);
  const unread = isUnread(notification);
  const busy = view.busyId === action.connectionId && action.connectionId !== null;
  const failed = view.actionErrorId === action.connectionId && action.connectionId !== null;
  const name = actorName(notification);
  const subtitle = notificationSubtitle(notification);
  const time = formatNotificationTime(notification.created_at);

  const open = () => {
    view.markRead(notification);
    const connectionId = connectionIdFromNotification(notification);
    if (connectionId) {
      const connection = view.connections?.find((row) => row.id === connectionId);
      if (connection?.user?.public_id) {
        router.push(`/user/${connection.user.public_id}` as never);
        return;
      }
      router.push('/connections' as never);
      return;
    }
    if (notification.data?.conversation_id) {
      router.push(`/conversation/${notification.data.conversation_id}` as never);
    }
  };

  return (
    <Pressable
      onPress={open}
      accessibilityRole="button"
      accessibilityLabel={`${notification.title}${unread ? ', unread' : ''}`}
      accessibilityHint={
        action.kind === 'accept'
          ? `Open the sender's profile or the connections list`
          : 'Marks this notification read'
      }
      testID={`notification-${notification.id}`}
      style={({ pressed }) => [styles.row, pressed ? styles.rowPressed : null]}>
      <Avatar
        name={name.length > 0 ? name : 'Notification'}
        src={notification.actor?.avatar_url ?? null}
        size={40}
      />

      <View style={styles.identity}>
        <AppText variant="body" weight={unread ? 'semibold' : 'regular'} numberOfLines={3}>
          {notification.title}
        </AppText>
        {subtitle ? (
          <AppText variant="small" tone="secondary" numberOfLines={2}>
            {subtitle}
          </AppText>
        ) : null}
        <View style={styles.meta}>
          {time ? (
            <AppText variant="caption" tone="tertiary">
              {time}
            </AppText>
          ) : null}
          {unread ? (
            <View
              style={styles.unreadDot}
              accessibilityElementsHidden
              importantForAccessibility="no"
            />
          ) : null}
        </View>

        {/*
          The only actions this build offers live here, and only when the
          notification's own `data` names the connection to resolve. Both wait
          for the server; the row stays (with a busy affordance) until the
          refetch removes or reconciles it ΓÇö nothing above is optimistically
          dismissed.
        */}
        {action.kind === 'accept' && action.connectionId ? (
          <View style={styles.actions}>
            <Button
              label="Accept"
              loading={busy}
              disabled={busy}
              accessibilityHint={`Accepts the connection request from ${name}`}
              onPress={() => view.accept(notification)}
              style={styles.action}
            />
            <Button
              label="Reject"
              variant="ghost"
              disabled={busy}
              accessibilityHint={`Rejects the connection request from ${name}`}
              onPress={() => view.reject(notification)}
              style={styles.action}
            />
          </View>
        ) : null}

        {failed && view.actionError ? (
          <AppText variant="caption" tone="danger" accessibilityLiveRegion="polite">
            {view.actionError}
          </AppText>
        ) : null}
      </View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  title: {
    marginBottom: spacing.lg,
    marginTop: spacing.sm,
  },
  stack: {
    gap: spacing.md,
  },
  row: {
    alignItems: 'flex-start',
    borderRadius: 12,
    flexDirection: 'row',
    gap: spacing.md,
    minHeight: layout.touchTargetSecondary,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.md,
  },
  rowPressed: {
    opacity: 0.85,
  },
  identity: {
    flex: 1,
    gap: spacing.xs,
  },
  meta: {
    alignItems: 'center',
    flexDirection: 'row',
    gap: spacing.sm,
  },
  unreadDot: {
    // Never the only signal ΓÇö the title is semibold when unread ΓÇö but a visual
    // the sighted eye scans for in a list.
    backgroundColor: colors.colorPrimary,
    borderRadius: 4,
    height: 8,
    width: 8,
  },
  actions: {
    flexDirection: 'row',
    gap: spacing.md,
    marginTop: spacing.sm,
  },
  action: {
    flex: 1,
  },
  tabBar: {
    flexDirection: 'row',
    gap: spacing.sm,
    marginBottom: spacing.md,
    paddingHorizontal: spacing.md,
  },
  tab: {
    paddingVertical: spacing.sm,
    paddingHorizontal: spacing.md,
    borderRadius: 8,
    alignItems: 'center',
  },
  tabActive: {
    backgroundColor: colors.colorPrimarySubtle,
  },
  tabPressed: {
    opacity: 0.8,
  },
  toolbar: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: spacing.md,
    marginVertical: spacing.md,
    paddingHorizontal: spacing.md,
  },
  toolbarButton: {
    paddingVertical: spacing.sm,
    paddingHorizontal: spacing.md,
    borderRadius: 8,
  },
  list: {
    paddingHorizontal: spacing.md,
    paddingBottom: spacing.lg,
  },
});

